#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class LcdTextTask final {
public:
 enum class Kind {RawData,Data,DirectData,Initialize,Cursor,Cgram,Spaces,FirstLine,SecondLine,Character,String};
 enum class Stage {Retain,Bind,Read,SelectEnd,DispatchCharacter,RepeatString,Restore,Return,PrepareFirst,PublishFirst,PrepareStrobe,PublishStrobe,PublishData,Pause1,Pause2,Pause3,PrepareRelease,PublishRelease,Ready,CompareAddress,SelectAddress,PrepareWrap,Wrap,ReadyAgain,RestoreData,DispatchData,PrepareCommand1,Command1,PrepareCommand2,Command2,PrepareCommand3,Command3,CursorValue,CursorCommand,PrepareSpace,WriteSpace,DecrementSpaces,RepeatSpaces,PrepareLine,LineCursor,CountLine,LineSpaces,PrepareLineAgain,LineCursorAgain,TestSign,SelectSign,CompareClear,SelectClear,ClearSecond,ClearFirst,CompareControl,SelectControl,AdjustControl,ControlCommand,Complete};
 enum class Write {Port,Data};
 LcdTextTask(Kind k=Kind::RawData,uint8_t value=0,uint8_t count=0,uint32_t source=0):kind_(k),stage_(k==Kind::Initialize?Stage::PrepareCommand1:k==Kind::Cursor||k==Kind::Cgram?Stage::CursorValue:k==Kind::Spaces?Stage::PrepareSpace:k==Kind::FirstLine||k==Kind::SecondLine?Stage::PrepareLine:k==Kind::Character?Stage::TestSign:Stage::Retain),value_(value),original_(value),count_(count),source_(source){}
 Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}unsigned path()const{return path_;}unsigned index()const{return index_;}uint32_t source()const{return source_;}uint8_t value()const{return value_;}uint8_t original()const{return original_;}uint8_t count()const{return count_;}
 bool resumeChild(uint8_t result){if(!waiting_)return false;waiting_=false;if(kind_==Kind::Data)status_=result;return true;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Retain:return kind_==Kind::String?c.pushLong:c.pushWord;case Stage::Read:return 5+c.read;case Stage::Restore:return kind_==Kind::String?c.popLong:c.popWord;case Stage::RestoreData:return c.popWord;case Stage::Return:return c.ret;case Stage::PublishFirst:case Stage::PublishStrobe:case Stage::PublishData:case Stage::PublishRelease:return 3+c.write;case Stage::Ready:case Stage::DispatchData:return kind_==Kind::DirectData||kind_==Kind::Character?c.call:c.shortCall;case Stage::Wrap:case Stage::ControlCommand:return c.call;case Stage::ReadyAgain:case Stage::Command1:case Stage::Command2:case Stage::Command3:case Stage::WriteSpace:case Stage::LineCursor:case Stage::LineSpaces:case Stage::LineCursorAgain:case Stage::ClearSecond:case Stage::ClearFirst:case Stage::DispatchCharacter:return c.shortCall;case Stage::CursorCommand:return kind_==Kind::Cgram?c.call:c.shortCall;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){
 case Stage::Retain:next=kind_==Kind::String?Stage::Bind:kind_==Kind::RawData?Stage::PrepareFirst:Stage::Ready;break;
 case Stage::Bind:next=Stage::Read;break;case Stage::Read:value_=uint8_t(read(index_++));break;case Stage::SelectEnd:next=value_?Stage::DispatchCharacter:Stage::Restore;break;case Stage::DispatchCharacter:waiting_=true;next=Stage::RepeatString;break;case Stage::RepeatString:next=Stage::Read;break;case Stage::Restore:next=Stage::Return;break;case Stage::Return:next=Stage::Complete;break;
 case Stage::PrepareFirst:value_=0x48;break;case Stage::PublishFirst:write(Write::Port,value_);break;case Stage::PrepareStrobe:value_=0xc8;break;case Stage::PublishStrobe:write(Write::Port,value_);break;case Stage::PublishData:write(Write::Data,original_);break;case Stage::Pause3:next=Stage::PrepareRelease;break;case Stage::PrepareRelease:value_=0x48;break;case Stage::PublishRelease:write(Write::Port,value_);next=Stage::Restore;break;
 case Stage::Ready:waiting_=true;next=kind_==Kind::DirectData?Stage::RestoreData:Stage::CompareAddress;break;case Stage::SelectAddress:next=status_==8?Stage::PrepareWrap:Stage::RestoreData;break;case Stage::PrepareWrap:value_=0xc0;next=Stage::Wrap;break;case Stage::Wrap:waiting_=true;next=Stage::ReadyAgain;break;case Stage::ReadyAgain:waiting_=true;next=Stage::RestoreData;break;case Stage::RestoreData:next=Stage::DispatchData;break;case Stage::DispatchData:waiting_=true;next=Stage::Return;break;
 case Stage::PrepareCommand1:value_=0x38;break;case Stage::Command1:waiting_=true;next=Stage::PrepareCommand2;break;case Stage::PrepareCommand2:value_=0x0c;break;case Stage::Command2:waiting_=true;next=Stage::PrepareCommand3;break;case Stage::PrepareCommand3:value_=1;break;case Stage::Command3:waiting_=true;next=Stage::Return;break;
 case Stage::CursorValue:value_=uint8_t(value_+(kind_==Kind::Cgram?0x40:0x80));next=Stage::CursorCommand;break;case Stage::CursorCommand:waiting_=true;next=Stage::Return;break;
 case Stage::PrepareSpace:value_=0x20;next=Stage::WriteSpace;break;case Stage::WriteSpace:waiting_=true;next=Stage::DecrementSpaces;break;case Stage::DecrementSpaces:--count_;break;case Stage::RepeatSpaces:next=count_?Stage::WriteSpace:Stage::Return;break;
 case Stage::PrepareLine:case Stage::PrepareLineAgain:value_=kind_==Kind::SecondLine?0x40:0;next=stage_==Stage::PrepareLine?Stage::LineCursor:Stage::LineCursorAgain;break;case Stage::LineCursor:waiting_=true;next=Stage::CountLine;break;case Stage::CountLine:count_=8;next=Stage::LineSpaces;break;case Stage::LineSpaces:waiting_=true;next=Stage::PrepareLineAgain;break;case Stage::LineCursorAgain:waiting_=true;next=Stage::Return;break;
 case Stage::TestSign:next=Stage::SelectSign;break;case Stage::SelectSign:path_=(value_&0x80)?2:0;next=path_?Stage::CompareClear:Stage::DispatchData;break;case Stage::SelectClear:if(value_==255){path_=1;next=Stage::ClearSecond;}else next=Stage::CompareControl;break;case Stage::ClearSecond:waiting_=true;next=Stage::ClearFirst;break;case Stage::ClearFirst:waiting_=true;next=Stage::Return;break;case Stage::SelectControl:next=value_<0x88?Stage::ControlCommand:Stage::AdjustControl;break;case Stage::AdjustControl:value_=uint8_t(value_+0x38);break;case Stage::ControlCommand:waiting_=true;next=Stage::Return;break;
 default:break;}stage_=next;return cost;}
private:Kind kind_;Stage stage_;uint8_t value_=0,original_=0,count_=0,status_=0;uint32_t source_=0;unsigned index_=0,path_=0;bool waiting_=false;
};
}
